    # Check the cheapest possible one-tap plan before input-axis allocation.
    minimum=math.prod(shape)*(seed.itemsize*2+2)+axis_bytes+seed.nbytes
    if max(minimum,axis_bytes*2)>_WORKSPACE_BYTES:return None
