        if self._grad_node is not None:raise RuntimeError('Only leaf tensors can change requires_grad flags')
        self.requires_grad_(flag)

    @property
    def _parents(self):
        node = self._grad_node
        return () if node is None else node._parents

    @property
    def _joint_vjp(self):
