            warnings.warn('Tensor.T on tensors with more than two dimensions is deprecated.',UserWarning,stacklevel=2)
            _state._high_rank_t_warning_emitted=True
        return self.permute(tuple(reversed(range(self.ndim))))
    @property
    def mT(self):
